import{_ as r}from"./chunks/7.BKtHZPne.js";import{_ as o}from"./chunks/image2.HkWvAWyN.js";import{_ as n}from"./chunks/image9.mdusDD_2.js";import{_ as s}from"./chunks/image.DulzA3w8.js";import{_ as l}from"./chunks/image1.q8qG2xMV.js";import{_ as t}from"./chunks/image.CkzfItEJ.js";import{_ as d}from"./chunks/image3.D136wQjp.js";import{_ as c}from"./chunks/100.DTsjWFW8.js";import{_ as h}from"./chunks/community.B_BmtdCL.js";import{_ as g,C as p,o as u,c as m,ak as a,E as f}from"./chunks/framework.CoNAY_Ta.js";const _="/projects/AiBlock/en/starter-kit/assets/1.C-dMUPzU.webp",w="/projects/AiBlock/en/starter-kit/assets/4.BYGZCChn.webp",b="/projects/AiBlock/en/starter-kit/assets/2.DoAYodVs.webp",H=JSON.parse('{"title":"3.7 Rotating Swing Ride","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Builds/3.7 Rotating Swing Ride.md","filePath":"docs/3. Creative Builds/3.7 Rotating Swing Ride.md"}'),y={name:"docs/3. Creative Builds/3.7 Rotating Swing Ride.md"};function k(v,e,x,P,q,S){const i=p("Pdf");return u(),m("div",null,[e[0]||(e[0]=a('<h1 id="_3-7-rotating-swing-ride" tabindex="-1">3.7 Rotating Swing Ride <a class="header-anchor" href="#_3-7-rotating-swing-ride" aria-label="Permalink to &quot;3.7 Rotating Swing Ride&quot;">​</a></h1><h2 id="_3-7-1-lesson-introduction" tabindex="-1">3.7.1 Lesson Introduction <a class="header-anchor" href="#_3-7-1-lesson-introduction" aria-label="Permalink to &quot;3.7.1 Lesson Introduction&quot;">​</a></h2><p>Inspired by amusement park swing rides, this lesson guides the assembly of a miniature motorized rotating swing ride. The lesson introduces physical principles related to centrifugal force, covers multi-speed motor programming, and teaches structural balance assembly techniques. Hands-on testing demonstrates the relationship between rotational speed and swing flare angle, establishing a cause-and-effect understanding between speed, force, and physical form while solidifying the foundation for dynamic mechanical builds.</p><img loading="lazy" height="1662" width="1662" src="'+r+'" class="common_img" style="width:400px;"><h2 id="_3-7-2-learning-objectives" tabindex="-1">3.7.2 Learning Objectives <a class="header-anchor" href="#_3-7-2-learning-objectives" aria-label="Permalink to &quot;3.7.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand the concept and generation of centrifugal force. Master the laws of force equilibrium. Recognize the positive correlation between rotational speed and centrifugal force. Consolidate motor speed control programming.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the complete rotating swing ride independently. Program multi-speed motor regulation proficiently. Adjust rotational speeds to observe and verify changes in swing flare angles.</p></li><li><p><strong>Thinking Objectives</strong>: Establish physical thinking regarding circular motion and centrifugal force. Understand force equilibrium logic. Cultivate causal reasoning and engineering awareness of structural balance.</p></li><li><p><strong>Application Objectives</strong>: Identify diverse applications of centrifugal force in everyday life and industry. Understand the practical utility of rotary motion to stimulate curiosity about physical phenomena.</p></li></ol><h2 id="_3-7-3-preparation" tabindex="-1">3.7.3 Preparation <a class="header-anchor" href="#_3-7-3-preparation" aria-label="Permalink to &quot;3.7.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-7-4-hands-on-project" tabindex="-1">3.7.4 Hands-On Project <a class="header-anchor" href="#_3-7-4-hands-on-project" aria-label="Permalink to &quot;3.7.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project for this lesson is an electric rotating swing ride, where a motor drives a turntable to rotate, causing the suspended chairs to flare outward due to centrifugal force. The underlying physics involves force equilibrium: each chair experiences gravity, tension, and centrifugal force, stabilizing at a specific angle when the three forces reach balance. Rotational speed dictates the flare angle: higher speeds generate greater centrifugal force, causing chairs to swing out farther. The program uses button inputs to start, stop, and regulate motor speed. Stepping through progressive speeds verifies the relationship between speed and centrifugal force while providing hands-on practice in multi-speed motor programming.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),f(i,{src:"../../_static/shared/pdf/chapter_3/7.pdf"}),e[1]||(e[1]=a('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li>Connect the 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</li></ul><img loading="lazy" height="1105" width="1594" src="'+_+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+o+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="193" width="589" src="'+n+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+s+'"></td><td style="text-align:left;">Triggers corresponding blocks when the button is short-pressed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="148" width="624" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+t+'"></td><td style="text-align:left;">Sets the operating speed and rotation direction of the designated motor</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="64" width="358" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+t+'"></td><td style="text-align:left;">Stops the motor connected to the selected port</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="620" width="430" src="'+w+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>After powering on, short-pressing the left and right buttons acts as dual trigger conditions: short-pressing the left button sets motor S1 to rotate forward at 20% speed, while short-pressing the right button stops motor S1.</p></li></ul><img loading="lazy" height="280" width="575" src="'+b+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+c+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1xyD_-3msc3KcaGQHLqkcPOZNSNXFIirT?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-7-5-expansion-and-challenge" tabindex="-1">3.7.5 Expansion and Challenge <a class="header-anchor" href="#_3-7-5-expansion-and-challenge" aria-label="Permalink to &quot;3.7.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Three-Speed Selectable Swing Ride</strong></p><p>Design three speed settings: pressing the left button cycles sequentially through low speed at 10%, medium speed at 20%, and high speed at 30%, while pressing the right button stops the motor. Use a variable to track the current speed tier, incrementing the value with each left button press and adjusting motor speed accordingly. This exercises variable counting and multi-branch logic, providing button-driven speed regulation that mirrors real amusement park rides.</p><p><strong>Project 2: Illuminated Musical Carousel</strong></p><p>Attach colored streamers or small LEDs to the swing ride, creating a vibrant halo of light during rotation. Incorporate an ultrasonic sensor to start spinning and flash lights automatically when someone approaches, then stop when no one is present. Practice multi-actuator coordination and sensor-driven triggers to construct an interactive greeting swing ride.</p><h2 id="_3-7-6-q-a" tabindex="-1">3.7.6 Q&amp;A <a class="header-anchor" href="#_3-7-6-q-a" aria-label="Permalink to &quot;3.7.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why does the swing chair flare outward at a larger angle as the ride spins faster?</strong></p><p>Answer: Rotation produces centrifugal force. As the swing chair orbits the center, it experiences an outward-directed inertia known as centrifugal force. Centrifugal force correlates with rotational speed: slower rotation generates minimal force so chairs hang nearly vertical, whereas faster rotation generates substantial force pulling chairs outward vigorously. The suspended linkage exerts an inward tension to hold the chair in place. When outward centrifugal force, inward tension, and downward gravitational force achieve balance, the chair settles into a tilted rotating equilibrium. Faster speeds require a greater tilt angle so the horizontal component of tension balances the stronger centrifugal force, widening the flare angle.</p><p><strong>Question 2: How is motor speed controlled? Why does changing a number alter rotation speed?</strong></p><p>Answer: Motor speed relies on pulse width modulation, also known as PWM, which modulates effective output power by varying the ratio of powered-on time. Percentage figures in the program, such as 10% or 20%, represent the PWM duty cycle, reflecting the proportion of time power is supplied within each signal cycle. Higher percentages increase the energized duration per unit time, resulting in higher rotation speeds under a constant load. In contrast, lower percentages decrease powered duration, yielding slower speeds. The graphical software packages this underlying PWM circuitry into intuitive speed percentage blocks, allowing speed adjustments simply by modifying numerical values without dealing with low-level circuit design.</p><h2 id="_3-7-7-technical-support-and-product-discussion" tabindex="-1">3.7.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-7-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.7.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+h+'" class="common_img" style="width:800px;"></a>',29))])}const O=g(y,[["render",k]]);export{H as __pageData,O as default};
